import{_ as t,l,o as e,c as n,v as i,p as d,x as o,d as s,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"DFA 最小化与 Myhill–Nerode","description":"","frontmatter":{"title":"DFA 最小化与 Myhill–Nerode","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dfa-minimization.md","filePath":"cs/dfa-minimization.md","lastUpdated":1789023840000}'),m={name:"cs/dfa-minimization.md"};function f(A,a,c,_,D,F){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="dfa-最小化与-myhill–nerode" tabindex="-1">DFA 最小化与 Myhill–Nerode <a class="header-anchor" href="#dfa-最小化与-myhill–nerode" aria-label="Permalink to &quot;DFA 最小化与 Myhill–Nerode&quot;">​</a></h1><div class="epigraph"><p>正则语言对应字母表上的有限指数右同余；等价类就是最小 DFA 的状态，个数是语言的固有不变量。</p><footer>—— 据 Nerode, Linear Automaton Transformations, 1958；Hopcroft, 1971 整理</footer></div><p>上一课<a href="/cs/pumping-lemma-regular">泵引理</a>给出排除正则的必要性质，并点名「有些非正则可泵」。本课不重写博弈。缺口是<strong>充要刻画</strong>：Myhill–Nerode 等价类有限当且仅当语言正则，并且最小 DFA 在同构意义下唯一。主干<a href="/cs/nfa-dfa">NFA/DFA</a>只说过「确定化之后可再压状态」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一正则语言可以有许多 DFA，状态数从子集构造的 \\(2^{|Q|}\\) 到「刚好够用」。何谓够用？对 \\(x,y\\in\\Sigma^*\\)，定义 \\(x\\sim_L y\\) 当且仅当 \\(\\forall z,\\ xz\\in L\\iff yz\\in L\\)。这是右同余。指数（等价类个数）有限 \\(\\iff\\) \\(L\\) 正则。每个类做成一个状态，\\(\\delta([x],a)=[xa]\\)，接受类是那些 \\(x\\in L\\)。</p><p>泵引理看不到「两个前缀是否永远可互换」。\\(\\{a^nb^n\\}\\) 的前缀 \\(a^i\\) 两两不等价（后面跟 \\(b^i\\) 才能分），指数无穷，故非正则——这补上泵失败时的工具。</p><h3 id="最小不是「看起来少」" tabindex="-1">最小不是「看起来少」 <a class="header-anchor" href="#最小不是「看起来少」" aria-label="Permalink to &quot;最小不是「看起来少」&quot;">​</a></h3><p>任意 DFA 可按可区分性合并：两状态 \\(p,q\\) 可区分，若存在 \\(z\\) 使恰好一个走到接受。Hopcroft 划分细化给出 \\(O(|Q||\\Sigma|\\log|Q|)\\) 算法。最小化结果与 Nerode 自动机同构。少一个状态就会认错语言。</p><p><span class="marginnote">Nerode 1958；Myhill 的同余更偏句法。Hopcroft 1971 最小化是词法生成器的标准步骤。本课要的是不变量 \\(|Q_{\\min}|\\)，不手写全部划分表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对给定 \\(L\\)，尝试列出无穷多两两可区分的前缀，即证非正则。对给定 DFA，算不可区分划分，商自动机即最小。不要把 NFA 最小化当多项式问题——NFA 最小状态数是难的，本课对象是 DFA。</p>',11)),(e(),d(h,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E8%AF%AD%E8%A8%80%20L%22%5D%20--%3E%20MN%5B%22Nerode%20%E7%AD%89%E4%BB%B7%E7%B1%BB%22%5D%0A%20%20MN%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%20DFA%22%5D%0A%20%20DFA%5B%22%E4%BB%BB%E6%84%8F%20DFA%22%5D%20--%3E%20PART%5B%22%E5%8F%AF%E5%8C%BA%E5%88%86%E5%88%92%E5%88%86%22%5D%0A%20%20PART%20--%3E%20MIN%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p><a href="/cs/thompson-nfa">Thompson</a> 与子集构造之后接本课，才得到词法器里那张紧表。本补层不重做构造，只收等价类。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(|Q_{\\min}|\\) 是语言的复杂度，与具体正则式写法无关。指数无穷就是「需要无限记忆的前缀」。后课封闭性证明常构造乘积自动机，再最小化只是工程；正确性不依赖最小。</p><p>不要用状态数比较 NFA 与 DFA 的「谁更强」：语言类相同，状态可以指数分开。</p><p>Hopcroft 划分从「接受/拒绝」两块出发，用字母表符号细化，直到稳定。实现是词法生成器的标准后段，本课要的是：最小状态数是 \\(L\\) 的不变量，与你怎么写正则式无关。NFA 状态数可以远小于 DFA，但不能拿来当 Myhill–Nerode 指数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Hopcroft 算法的对数因子，不讨论 NFA 最小化的 PSPACE 性。不把 Myhill–Nerode 推广到树自动机。后课默认：正则 \\(\\iff\\) 有限指数右同余；谈「唯一最小 DFA」即这个对象。封闭性是下一课在运算下保持这一类。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\sim_L\\) 有限指数当且仅当 \\(L\\) 正则；类即最小状态。</li><li>DFA 按可区分性商掉，结果唯一。</li><li>无穷多可区分前缀 \\(\\Rightarrow\\) 非正则，补泵引理。</li><li>出处：Nerode, 1958；Hopcroft, 1971。</li></ul>',9))])}const E=t(m,[["render",f]]);export{u as __pageData,E as default};
